-- ivis-server PostgreSQL schema, version 2. GENERATED by docs/plans/postgresql-state/render_schema.py.
-- Chart adaptation: idempotent CREATE and migration insert; apply to public as the existing owner.
--   psql "$IVIS_ADMIN_DSN" -v ON_ERROR_STOP=1 -f sql/postgres/001_schema.sql
-- Re-running preserves existing tables and rows. This is installation DDL, not an upgrade migration.
-- PostgreSQL 16+. No DROP/TRUNCATE; credentials never belong in this file.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- 명시적으로 적용한 DDL 버전
CREATE TABLE IF NOT EXISTS ivis_schema_migration (
    version INTEGER NOT NULL CHECK (version > 0),
    name TEXT NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (version)
);

-- 상태 세대(generation) 한 개: 이름과 활성 여부. 코드가 정하는 버전(관계 규칙 등)은 여기에 두지 않는다
CREATE TABLE IF NOT EXISTS ivis_projection (
    generation_id INTEGER GENERATED ALWAYS AS IDENTITY NOT NULL,
    name TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('building','active','frozen','retired')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (generation_id),
    UNIQUE (name)
);

-- revision 원장: 내용이 바뀐 공개(publication)마다 한 행
CREATE TABLE IF NOT EXISTS ivis_commit (
    generation_id INTEGER NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    kind TEXT NOT NULL CHECK (kind IN ('init','bootstrap','apply')),
    published_at_ns NUMERIC(30,0) NOT NULL,
    state_digest TEXT NOT NULL CHECK (state_digest ~ '^[0-9a-f]{64}$'),
    changed_objects INTEGER NOT NULL CHECK (changed_objects >= 0),
    PRIMARY KEY (generation_id, revision),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);

-- 세대의 현재 head와 처리 위치(cursor). 객체와 같은 transaction으로 갱신
CREATE TABLE IF NOT EXISTS ivis_checkpoint (
    generation_id INTEGER NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    bootstrapped BOOLEAN NOT NULL,
    trigger_identity JSONB CHECK (trigger_identity IS NULL OR jsonb_typeof(trigger_identity) = 'object'),
    positions JSONB NOT NULL CHECK (jsonb_typeof(positions) = 'object'),
    metadata JSONB NOT NULL CHECK (jsonb_typeof(metadata) = 'object'),
    state_digest TEXT NOT NULL CHECK (state_digest ~ '^[0-9a-f]{64}$'),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (generation_id),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT,
    FOREIGN KEY (generation_id, revision) REFERENCES ivis_commit (generation_id, revision) ON DELETE RESTRICT
);

-- 원천 좌표 한 개를 이미 받았다는 증거(같은 좌표 다른 payload 거부용). raw 아님
CREATE TABLE IF NOT EXISTS ivis_observation_receipt (
    generation_id INTEGER NOT NULL,
    observation_key_digest BYTEA NOT NULL CHECK (octet_length(observation_key_digest) = 32),
    observation_key TEXT NOT NULL,
    safe_projection_digest BYTEA NOT NULL CHECK (octet_length(safe_projection_digest) = 32),
    projection_profile TEXT,
    first_revision BIGINT NOT NULL CHECK (first_revision >= 0),
    PRIMARY KEY (generation_id, observation_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);

-- 관계 엔진 입력인 최신 safe 객체(native/provisional). 삭제는 deleted=true 행으로 유지
CREATE TABLE IF NOT EXISTS ivis_object_state (
    generation_id INTEGER NOT NULL,
    object_key_digest BYTEA NOT NULL CHECK (octet_length(object_key_digest) = 32),
    object_key TEXT NOT NULL,
    cluster_uid TEXT,
    cluster_name TEXT,
    object_uid TEXT,
    api_version TEXT,
    kind TEXT,
    namespace TEXT,
    name TEXT,
    deleted BOOLEAN NOT NULL,
    effective_time_ns NUMERIC(30,0),
    projection_profile TEXT,
    safe_payload TEXT NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    PRIMARY KEY (generation_id, object_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ivis_object_state_kind_scope_idx ON ivis_object_state (generation_id, kind, namespace);

-- 그래프 entity(native/provisional/derived 전부). K8s Node만 뜻하지 않는다
CREATE TABLE IF NOT EXISTS ivis_entity_state (
    generation_id INTEGER NOT NULL,
    entity_key_digest BYTEA NOT NULL CHECK (octet_length(entity_key_digest) = 32),
    entity_id TEXT NOT NULL,
    identity_class TEXT NOT NULL CHECK (identity_class IN ('strong','provisional','derived')),
    cluster_uid TEXT,
    cluster_name TEXT,
    object_uid TEXT,
    kind TEXT,
    namespace TEXT,
    name TEXT,
    safe_payload TEXT NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    PRIMARY KEY (generation_id, entity_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ivis_entity_state_kind_scope_idx ON ivis_entity_state (generation_id, kind, namespace);

-- K8s Node 전용 현재 상태·구성 read-model(객체에서 결정적으로 파생)
CREATE TABLE IF NOT EXISTS ivis_node_state (
    generation_id INTEGER NOT NULL,
    object_key_digest BYTEA NOT NULL CHECK (octet_length(object_key_digest) = 32),
    entity_id TEXT,
    cluster_uid TEXT,
    cluster_name TEXT,
    node_uid TEXT,
    node_name TEXT,
    lifecycle TEXT NOT NULL CHECK (lifecycle IN ('present_observation','terminating','deleted')),
    readiness TEXT NOT NULL CHECK (readiness IN ('ready','not_ready','unknown')),
    readiness_quality TEXT NOT NULL,
    ready_status TEXT CHECK (ready_status IS NULL OR ready_status IN ('True','False','Unknown')),
    memory_pressure_status TEXT CHECK (memory_pressure_status IS NULL OR memory_pressure_status IN ('True','False','Unknown')),
    disk_pressure_status TEXT CHECK (disk_pressure_status IS NULL OR disk_pressure_status IN ('True','False','Unknown')),
    pid_pressure_status TEXT CHECK (pid_pressure_status IS NULL OR pid_pressure_status IN ('True','False','Unknown')),
    network_unavailable_status TEXT CHECK (network_unavailable_status IS NULL OR network_unavailable_status IN ('True','False','Unknown')),
    unschedulable BOOLEAN,
    conditions JSONB CHECK (conditions IS NULL OR jsonb_typeof(conditions) = 'array'),
    taints JSONB CHECK (taints IS NULL OR jsonb_typeof(taints) = 'array'),
    capacity JSONB CHECK (capacity IS NULL OR jsonb_typeof(capacity) = 'object'),
    allocatable JSONB CHECK (allocatable IS NULL OR jsonb_typeof(allocatable) = 'object'),
    architecture TEXT,
    operating_system TEXT,
    os_image TEXT,
    kernel_version TEXT,
    kubelet_version TEXT,
    container_runtime_version TEXT,
    addresses JSONB CHECK (addresses IS NULL OR jsonb_typeof(addresses) = 'array'),
    pod_cidr TEXT,
    pod_cidrs JSONB CHECK (pod_cidrs IS NULL OR jsonb_typeof(pod_cidrs) = 'array'),
    field_quality JSONB NOT NULL CHECK (jsonb_typeof(field_quality) = 'object'),
    effective_time_ns NUMERIC(30,0),
    projection_profile TEXT,
    normalization_version INTEGER NOT NULL CHECK (normalization_version > 0),
    revision BIGINT NOT NULL CHECK (revision >= 0),
    PRIMARY KEY (generation_id, object_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT,
    FOREIGN KEY (generation_id, object_key_digest) REFERENCES ivis_object_state (generation_id, object_key_digest) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ivis_node_state_readiness_idx ON ivis_node_state (generation_id, cluster_uid, readiness);

-- Node 상태가 의미 있게 바뀐 시점의 이력(kubelet heartbeat만 바뀐 관측은 제외)
CREATE TABLE IF NOT EXISTS ivis_node_state_history (
    generation_id INTEGER NOT NULL,
    object_key_digest BYTEA NOT NULL CHECK (octet_length(object_key_digest) = 32),
    entity_id TEXT,
    cluster_uid TEXT,
    cluster_name TEXT,
    node_uid TEXT,
    node_name TEXT,
    lifecycle TEXT NOT NULL CHECK (lifecycle IN ('present_observation','terminating','deleted')),
    readiness TEXT NOT NULL CHECK (readiness IN ('ready','not_ready','unknown')),
    readiness_quality TEXT NOT NULL,
    ready_status TEXT CHECK (ready_status IS NULL OR ready_status IN ('True','False','Unknown')),
    memory_pressure_status TEXT CHECK (memory_pressure_status IS NULL OR memory_pressure_status IN ('True','False','Unknown')),
    disk_pressure_status TEXT CHECK (disk_pressure_status IS NULL OR disk_pressure_status IN ('True','False','Unknown')),
    pid_pressure_status TEXT CHECK (pid_pressure_status IS NULL OR pid_pressure_status IN ('True','False','Unknown')),
    network_unavailable_status TEXT CHECK (network_unavailable_status IS NULL OR network_unavailable_status IN ('True','False','Unknown')),
    unschedulable BOOLEAN,
    conditions JSONB CHECK (conditions IS NULL OR jsonb_typeof(conditions) = 'array'),
    taints JSONB CHECK (taints IS NULL OR jsonb_typeof(taints) = 'array'),
    capacity JSONB CHECK (capacity IS NULL OR jsonb_typeof(capacity) = 'object'),
    allocatable JSONB CHECK (allocatable IS NULL OR jsonb_typeof(allocatable) = 'object'),
    architecture TEXT,
    operating_system TEXT,
    os_image TEXT,
    kernel_version TEXT,
    kubelet_version TEXT,
    container_runtime_version TEXT,
    addresses JSONB CHECK (addresses IS NULL OR jsonb_typeof(addresses) = 'array'),
    pod_cidr TEXT,
    pod_cidrs JSONB CHECK (pod_cidrs IS NULL OR jsonb_typeof(pod_cidrs) = 'array'),
    field_quality JSONB NOT NULL CHECK (jsonb_typeof(field_quality) = 'object'),
    effective_time_ns NUMERIC(30,0),
    projection_profile TEXT,
    normalization_version INTEGER NOT NULL CHECK (normalization_version > 0),
    revision BIGINT NOT NULL CHECK (revision >= 0),
    published_at_ns NUMERIC(30,0) NOT NULL,
    PRIMARY KEY (generation_id, object_key_digest, revision),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);

-- 현재 해소된 의미 관계(선언 관계이지 실측 traffic/I/O 아님)
CREATE TABLE IF NOT EXISTS ivis_relation_state (
    generation_id INTEGER NOT NULL,
    relation_key_digest BYTEA NOT NULL CHECK (octet_length(relation_key_digest) = 32),
    relation_key TEXT NOT NULL,
    relation_type TEXT NOT NULL,
    source_entity_id TEXT NOT NULL,
    target_entity_id TEXT NOT NULL,
    source_entity_digest BYTEA NOT NULL CHECK (octet_length(source_entity_digest) = 32),
    target_entity_digest BYTEA NOT NULL CHECK (octet_length(target_entity_digest) = 32),
    evidence_path TEXT,
    safe_payload TEXT NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    PRIMARY KEY (generation_id, relation_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ivis_relation_state_outgoing_idx ON ivis_relation_state (generation_id, source_entity_digest, relation_type);
CREATE INDEX IF NOT EXISTS ivis_relation_state_incoming_idx ON ivis_relation_state (generation_id, target_entity_digest, relation_type);

-- 현재 미해결(unresolved) 참조 선언. 해소된 선언은 ivis_relation_state
CREATE TABLE IF NOT EXISTS ivis_reference_state (
    generation_id INTEGER NOT NULL,
    reference_key_digest BYTEA NOT NULL CHECK (octet_length(reference_key_digest) = 32),
    reference_key TEXT NOT NULL,
    relation_type TEXT NOT NULL,
    source_entity_id TEXT NOT NULL,
    source_entity_digest BYTEA NOT NULL CHECK (octet_length(source_entity_digest) = 32),
    reason TEXT NOT NULL,
    safe_payload TEXT NOT NULL,
    revision BIGINT NOT NULL CHECK (revision >= 0),
    PRIMARY KEY (generation_id, reference_key_digest),
    FOREIGN KEY (generation_id) REFERENCES ivis_projection (generation_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ivis_reference_state_source_idx ON ivis_reference_state (generation_id, source_entity_digest);

INSERT INTO ivis_schema_migration (version, name) VALUES (2, 'ivis state schema: objects, entities, relations, node state; cluster_name beside cluster_uid (cluster-match-v1)');
COMMIT;

SELECT version, name, applied_at FROM ivis_schema_migration ORDER BY version;
